  const isDark = document.body.classList.toggle('dark');
  document.getElementById('themeToggle').textContent = isDark ? 'too dark? 🌙' : 'too bright? ☀️';
}

// Focus Timer
let focusSeconds = 25 * 60;
let focusInterval = null;

function renderFocus() {
  const m = String(Math.floor(focusSeconds / 60)).padStart(2, '0');
  const s = String(focusSeconds % 60).padStart(2, '0');
  document.getElementById('focusDisplay').textContent = `${m}:${s}`;
}

function startTimer() {
  if (focusInterval) return;
  focusInterval = setInterval(() => {
    if (focusSeconds <= 0) { clearInterval(focusInterval); focusInterval = null; return; }
    focusSeconds--;
    renderFocus();
  }, 1000);
}

function stopTimer() {
  clearInterval(focusInterval);
  focusInterval = null;
}

function resetTimer() {
  stopTimer();
  focusSeconds = 25 * 60;
  renderFocus();
}

// Todos
let tasks = JSON.parse(localStorage.getItem('tasks') || '[]');

function saveTasks() {
  localStorage.setItem('tasks', JSON.stringify(tasks));
}

function renderTasks() {
  const list = document.getElementById('todoList');
  list.innerHTML = '';
  tasks.forEach((task, i) => {
    const li = document.createElement('li');
    li.className = 'todo-item' + (task.done ? ' done' : '');
    li.innerHTML = `
      <input type="checkbox" ${task.done ? 'checked' : ''} onchange="toggleTask(${i})">
      <span>${task.name}</span>
      <button onclick="deleteTask(${i})">✕</button>
    `;
    list.appendChild(li);
  });
}

function addTask(e) {
  e.preventDefault();
  const input = e.target.querySelector('.todo-input');
  tasks.push({ name: input.value.trim(), done: false });
  input.value = '';
  saveTasks();
  renderTasks();
}

function toggleTask(i) {
  tasks[i].done = !tasks[i].done;
  saveTasks();
  renderTasks();
}

function deleteTask(i) {
  tasks.splice(i, 1);
  saveTasks();
  renderTasks();
}

renderTasks();

