/* Quick Links */
.link-form {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.link-input {
  flex: 1;
  min-width: 80px;
  padding: 0.4rem 0.6rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: rgba(0, 0, 0, 0.05);
  color: #1a1a1a;
  font-size: 0.85rem;
  outline: none;
}

.link-input::placeholder { opacity: 0.4; }

.link-form button {
  padding: 0.4rem 0.8rem;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  background: rgba(0, 0, 0, 0.08);
  color: #1a1a1a;
  cursor: pointer;
  font-size: 0.85rem;
}

.link-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.link-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.link-item a {
  flex: 1;
  font-size: 0.9rem;
  color: #4a4af4;
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.link-item a:hover { text-decoration: underline; }

.link-item button {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  opacity: 0.4;
  font-size: 0.85rem;
  padding: 0;
}

